class Solution {
    public java.util.List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        int[] indexes = new int[n];
        int[] temp = new int[n];
        int[] counts = new int[n];
        for (int i = 0; i < n; i++) {
            indexes[i] = i;
        }
        mergeSort(nums, indexes, temp, counts, 0, n);
        java.util.List<Integer> result = new java.util.ArrayList<>();
        for (int value : counts) {
            result.add(value);
        }
        return result;
    }

    private void mergeSort(int[] nums, int[] indexes, int[] temp, int[] counts, int left, int right) {
        if (right - left <= 1) {
            return;
        }
        int mid = left + (right - left) / 2;
        mergeSort(nums, indexes, temp, counts, left, mid);
        mergeSort(nums, indexes, temp, counts, mid, right);
        merge(nums, indexes, temp, counts, left, mid, right);
    }

    private void merge(int[] nums, int[] indexes, int[] temp, int[] counts, int left, int mid, int right) {
        int i = left;
        int j = mid;
        int k = left;
        int rightMoved = 0;
        while (i < mid && j < right) {
            if (nums[indexes[j]] < nums[indexes[i]]) {
                rightMoved++;
                temp[k++] = indexes[j++];
            } else {
                counts[indexes[i]] += rightMoved;
                temp[k++] = indexes[i++];
            }
        }
        while (i < mid) {
            counts[indexes[i]] += rightMoved;
            temp[k++] = indexes[i++];
        }
        while (j < right) {
            temp[k++] = indexes[j++];
        }
        System.arraycopy(temp, left, indexes, left, right - left);
    }
}

class Solution {
    private int[] tree;

    public java.util.List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        int[] sorted = nums.clone();
        java.util.Arrays.sort(sorted);
        java.util.Map<Integer, Integer> ranks = new java.util.HashMap<>();
        int nextRank = 1;
        for (int value : sorted) {
            if (!ranks.containsKey(value)) {
                ranks.put(value, nextRank++);
            }
        }
        tree = new int[nextRank + 1];
        Integer[] answer = new Integer[n];
        for (int i = n - 1; i >= 0; i--) {
            int rank = ranks.get(nums[i]);
            answer[i] = query(rank - 1);
            update(rank);
        }
        return java.util.Arrays.asList(answer);
    }

    private void update(int index) {
        for (int i = index; i < tree.length; i += i & -i) {
            tree[i]++;
        }
    }

    private int query(int index) {
        int sum = 0;
        for (int i = index; i > 0; i -= i & -i) {
            sum += tree[i];
        }
        return sum;
    }
}

class Solution {
    private int[] tree;
    private int size;

    public java.util.List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        int[] sorted = nums.clone();
        java.util.Arrays.sort(sorted);
        java.util.Map<Integer, Integer> ranks = new java.util.HashMap<>();
        int nextRank = 1;
        for (int value : sorted) {
            if (!ranks.containsKey(value)) {
                ranks.put(value, nextRank++);
            }
        }
        size = 1;
        while (size < nextRank) {
            size <<= 1;
        }
        tree = new int[size * 2];
        Integer[] answer = new Integer[n];
        for (int i = n - 1; i >= 0; i--) {
            int rank = ranks.get(nums[i]);
            answer[i] = query(1, rank - 1);
            add(rank);
        }
        return java.util.Arrays.asList(answer);
    }

    private void add(int rank) {
        int index = rank + size - 1;
        while (index > 0) {
            tree[index]++;
            index >>= 1;
        }
    }

    private int query(int left, int right) {
        if (left > right) {
            return 0;
        }
        int sum = 0;
        int l = left + size - 1;
        int r = right + size - 1;
        while (l <= r) {
            if ((l & 1) == 1) {
                sum += tree[l++];
            }
            if ((r & 1) == 0) {
                sum += tree[r--];
            }
            l >>= 1;
            r >>= 1;
        }
        return sum;
    }
}

class Solution {
    private Node root;

    public java.util.List<Integer> countSmaller(int[] nums) {
        Integer[] answer = new Integer[nums.length];
        for (int i = nums.length - 1; i >= 0; i--) {
            root = insert(root, nums[i], 0, answer, i);
        }
        return java.util.Arrays.asList(answer);
    }

    private Node insert(Node node, int value, int smallerBefore, Integer[] answer, int index) {
        if (node == null) {
            answer[index] = smallerBefore;
            return new Node(value);
        }
        if (value == node.value) {
            node.duplicates++;
            answer[index] = smallerBefore + node.leftSize;
        } else if (value < node.value) {
            node.leftSize++;
            node.left = insert(node.left, value, smallerBefore, answer, index);
        } else {
            node.right = insert(node.right, value, smallerBefore + node.leftSize + node.duplicates, answer, index);
        }
        return node;
    }

    private static class Node {
        final int value;
        int leftSize;
        int duplicates = 1;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
        }
    }
}

class Solution {
    public java.util.List<Integer> countSmaller(int[] nums) {
        java.util.List<Integer> sorted = new java.util.ArrayList<>();
        Integer[] answer = new Integer[nums.length];
        for (int i = nums.length - 1; i >= 0; i--) {
            int position = lowerBound(sorted, nums[i]);
            answer[i] = position;
            sorted.add(position, nums[i]);
        }
        return java.util.Arrays.asList(answer);
    }

    private int lowerBound(java.util.List<Integer> values, int target) {
        int left = 0;
        int right = values.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values.get(mid) < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}
